import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    payslipExceldailog: Boolean,
    excelHeaders: Array,
    excelTableData: Array
  },
  components: {
    OverlayComp
  },
  data() {
    return {
      customerType: "",
      headerList: [],
      validInputData: [],
      overlay: false,
      menu: false,
      date1: ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"][Number(new Date().toISOString().split("T")[0].split("-")[1]) - 1] + " " + new Date().toISOString().split("T")[0].split("-")[0],
      date: new Date().toISOString().substr(0, 7),
      selectedItems: [],
      validHeaders: [],
      invalidHeaders: [],
      validInvalidTabs: 0,
      rules: {
        required: value => !!value || "Required.",
        email: value => {
          const pattern = /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
          return pattern.test(value) || "Invalid Email";
        }
      },
      dataTable: [],
      UploadList: [],
      isLoadingUpload: false,
      dynamicarrray: [],
      editStoreObj: {},
      dialogEdited: false
    };
  },
  watch: {
    payslipExceldailog: {
      async handler() {
        if (this.payslipExceldailog == true) {
          this.headerList = [];
          this.dataTable = [];
